#include <CGAL/Exact_predicates_exact_constructions_kernel.h>
#include <CGAL/Surface_mesh.h>
#include <CGAL/Polygon_mesh_processing/self_intersections.h>
#include <CGAL/Polygon_mesh_processing/intersection.h>
#include <CGAL/Polygon_mesh_processing/connected_components.h>
#include <CGAL/Polygon_mesh_processing/orientation.h>
#include <CGAL/Side_of_triangle_mesh.h>
#include <CGAL/boost/graph/helpers.h>
#include <fstream>
#include <iostream>
#include <vector>
#include <stdexcept>
using K=CGAL::Exact_predicates_exact_constructions_kernel;using M=CGAL::Surface_mesh<K::Point_3>;
M read(const char*name){bool binary=std::string(name).find(".meshbin")!=std::string::npos;std::ifstream in(name,binary?std::ios::binary:std::ios::in);uint64_t nv,nf;if(binary){in.read(reinterpret_cast<char*>(&nv),8);in.read(reinterpret_cast<char*>(&nf),8);}else in>>nv>>nf;if(!in)throw std::runtime_error("Missing source");M m;std::vector<M::Vertex_index>v;v.reserve(nv);for(uint64_t i=0;i<nv;++i){double p[3];if(binary)in.read(reinterpret_cast<char*>(p),24);else in>>p[0]>>p[1]>>p[2];v.push_back(m.add_vertex(K::Point_3(p[0],p[1],p[2])));}for(uint64_t i=0;i<nf;++i){uint64_t p[3];if(binary)in.read(reinterpret_cast<char*>(p),24);else in>>p[0]>>p[1]>>p[2];if(!in||p[0]>=nv||p[1]>=nv||p[2]>=nv||m.add_face(v[p[0]],v[p[1]],v[p[2]])==M::null_face())throw std::runtime_error("Invalid indexed face");}if(!CGAL::is_closed(m)||!CGAL::is_valid_polygon_mesh(m))throw std::runtime_error("Closed valid surface required");return m;}
int main(int argc,char**argv){if(argc!=4)return 2;bool self_a=false,self_b=false,cross=false,seed=false,out_a=false,out_b=false;size_t ca=0,cb=0,na=0,nb=0;std::string error;try{M a=read(argv[1]),b=read(argv[2]);na=a.number_of_faces();nb=b.number_of_faces();ca=CGAL::Polygon_mesh_processing::connected_components(a,a.add_property_map<M::Face_index,size_t>("f:cc",0).first);cb=CGAL::Polygon_mesh_processing::connected_components(b,b.add_property_map<M::Face_index,size_t>("f:cc",0).first);if(ca!=1||cb!=1)throw std::runtime_error("Exactly one boundary component required on each solid");self_a=CGAL::Polygon_mesh_processing::does_self_intersect(a);self_b=CGAL::Polygon_mesh_processing::does_self_intersect(b);if(self_a||self_b)throw std::runtime_error("Surface self intersection");out_a=CGAL::Polygon_mesh_processing::is_outward_oriented(a);out_b=CGAL::Polygon_mesh_processing::is_outward_oriented(b);if(!out_a||!out_b)throw std::runtime_error("Positive outward boundary orientation required");cross=CGAL::Polygon_mesh_processing::do_intersect(a,b,CGAL::parameters::do_overlap_test_of_bounded_sides(false));if(cross)throw std::runtime_error("Source and candidate boundaries intersect");CGAL::Side_of_triangle_mesh<M,K>side(a);seed=side(b.point(source(b.halfedge(*b.faces().begin()),b)))==CGAL::ON_BOUNDED_SIDE;if(!seed)throw std::runtime_error("Candidate lies outside source bounded domain");}catch(const std::exception&e){error=e.what();}std::ofstream o(argv[3]);o<<"{\"status\":\""<<(error.empty()?"complete_strict_domain_containment_passed":"strict_domain_refused")<<"\",\"error\":\""<<error<<"\",\"source_faces\":"<<na<<",\"candidate_faces\":"<<nb<<",\"source_components\":"<<ca<<",\"candidate_components\":"<<cb<<",\"source_self_intersection\":"<<(self_a?"true":"false")<<",\"candidate_self_intersection\":"<<(self_b?"true":"false")<<",\"source_outward_oriented\":"<<(out_a?"true":"false")<<",\"candidate_outward_oriented\":"<<(out_b?"true":"false")<<",\"boundary_intersections\":"<<(cross?"true":"false")<<",\"connected_boundary_seed_strictly_inside\":"<<(seed?"true":"false")<<",\"whole_bounded_solid_containment_proved\":"<<(error.empty()?"true":"false")<<",\"manufacturing_authorized\":false}\n";std::cout<<(error.empty()?"PASS":"REFUSED")<<" "<<error<<std::endl;return error.empty()?0:2;}
